import {esc,cash,icon,pageHead,dateLabel} from './ui.js';
import {getSummary} from './model.js';
import {getLearningDashboard,getLearningLesson,getLearningPractice,getLearningNudge} from './learning-model.js';
import {LEARNING_GOALS,LEARNING_TOPICS,LESSON_BY_ID} from './learning-content.js';
import {renderCampusGame,bindCampusGame,renderCampusGameEntry,bindCampusGameEntry} from './learning-game-ui.js';
import {getCampusGame} from './learning-game-model.js';
import {bindCampusMotion} from './learning-game-motion.js';
import {renderMoneyIQ,bindMoneyIQ} from './money-iq-ui.js';

const HOME={section:'learn',page:'money-iq'};
const learningMotionNext=new WeakMap(),learningMotionLast=new WeakMap();
const lux='<img src="/assets/lux-chat-2d.webp" alt="Lux, your Lumo learning buddy" width="92" height="92">';
const options=ctx=>({summary:getSummary(ctx.state)});
const model=ctx=>getLearningDashboard(ctx.state,options(ctx));
const ui=ctx=>(ctx.draft.learningUI ||= {lessonStory:{},reflection:{},revealed:{}});
const button=(label,action,{secondary=false,disabled=false,extra=''}={})=>`<button type="button" class="button${secondary?' secondary':''}" data-learn-action="${action}" ${extra} ${disabled?'disabled':''}>${label}</button>`;
const error=()=>'<p class="error learning-error" role="alert" data-learning-error></p>';
const header=(title,{back=true,settings=false}={})=>pageHead(title,{back,action:`<button type="button" class="learning-motion-toggle" data-learn-action="toggle-motion" aria-label="Animations on. Turn off" aria-pressed="true" title="Pause animations">${icon('repeat',17)}</button><button class="learning-home" data-learn-action="home" aria-label="Go to Home">${icon('home',17)}<span>Home</span></button>`});
const footer=html=>`<footer class="learning-footer">${html}</footer>`;
const reflectionTitle={
 'still-fits':'Plan still fits','adjusted-plan':'Plan updated','income-late':'Income changed','new-cost':'New cost','outside-spend':'Other money','example-reviewed':'I’d review my plan'
};
const tag=text=>`<span class="learning-tag">${esc(text)}</span>`;
function localPrivacy(ctx){return (model(ctx).effectivePersonalised??model(ctx).personalised)?'Using your recorded Lumo activity':'Practice with examples';}
function frame(title,body,{className='',back=true}={}){return `<section class="page learning-page ${className}">${header(title,{back})}${body}</section>`;}
function topicIcon(topic){return icon(topic.icon||'spark',22);}
function score(view){const level=view.level||{};return `<div class="learning-score"><div><span class="eyebrow">Your Lumo learning level</span><strong>${esc(level.title||level.name||'Getting started')}</strong><small>${esc(level.description||'Understanding grows one useful moment at a time.')}</small></div><span class="learning-level-number" aria-label="Level ${level.number||1}">${level.number||1}</span></div>`;}
function streakText(streak={}){if(streak.graceActive)return 'A little breathing room this week.';if(streak.completed)return 'This week’s learning is complete.';return `${streak.thisWeekActivities||0} of ${streak.target||2} activities this week`;}
function effectivePersonal(ctx){return ctx.state.account?.privacy?.personalisation!==false;}

function beats(active,labels=['The moment','Your move','The takeaway']){return `<div class="learning-beats" aria-label="${esc(labels[active])}">${labels.map((label,i)=>`<span class="${i<=active?'filled':''}" aria-hidden="true"></span>`).join('')}</div>`;}
function luxLine(text){return `<div class="learning-lux-line"><span>${lux}</span><p>${esc(text)}</p></div>`;}
function sceneFor(v){return v.scene||LESSON_BY_ID.get(v.id)?.scene||{eyebrow:'A campus money moment',headline:v.title,emoji:'✦',chat:[{name:'Lux',text:v.story}],choiceLabel:'What’s your move?',winTitle:'Now that’s a useful move.'};}
function sceneChat(scene,revealed=1,id=""){const chats=scene.chat||[];return `<div class="learning-scene-chat">${chats.slice(0,revealed).map((m,i)=>`<div class="learning-chat-bubble ${m.name==='Lux'?'from-lux':''}" style="--bubble-order:${i}"><span>${esc(m.name)}</span><p>${esc(m.text)}</p></div>`).join('')}${revealed<chats.length?`<button class="learning-chat-reply" data-learn-story-chat="${esc(id)}">${icon('chat',17)} ${chats[revealed]?.name==='Lux'?'Hear Lux’s take':'Next in the chat'} ${icon('arrow',17)}</button>`:''}</div>`;}
function storyFeature(v,{compact=false}={}){const scene=sceneFor(v);return `<button class="learning-feature ${compact?'compact':''}" data-learn-lesson="${esc(v.id)}"><span class="learning-feature-kicker">${esc(scene.eyebrow||'Today’s money moment')} · 1 min</span><strong>${esc(scene.headline||v.title)}</strong><span class="learning-feature-scene" aria-hidden="true"><span>${esc(scene.emoji||'✦')}</span><i>${lux}</i></span><span class="learning-feature-cta">${v.completed?'Revisit the story':'Step into the story'} ${icon('arrow',20)}</span></button>`;}
const moneyIQEntry=()=>`<button class="miq-learning-entry" data-learn-action="money-iq"><span>${icon('spark',22)}</span><div><strong>Money IQ</strong><small>Your week. Five quick guesses.</small></div>${icon('arrow',20)}</button>`;
function start(ctx){
 const d=ui(ctx),step=d.startStep||'welcome',saved=model(ctx),goal=d.goal||saved.goal||'',mode=d.mode||'';
 if(step==='welcome')return frame('Learn with Lux',`<div class="learning-body learning-payoff">${moneyIQEntry()}<div class="learning-lux-hero">${lux}</div><p class="eyebrow">Campus Run</p><h1>Campus has plans.<br>What’s your move?</h1><p class="learning-intro">Campus life. Your choices. Lux has your back.</p>${error()}</div>${footer(button('Play Campus Run','quick-play')+'<button class="learning-text" data-learn-action="choose-focus">Choose my learning focus</button>'+'<p class="learning-fine">Starts with story money. Your own balances stay private.</p>')}`,{className:'learning-task learning-game-welcome'});
 if(step==='mode')return frame('Make it yours',`${beats(1,['Your focus','Your examples','Let’s go'])}<div class="learning-body"><div class="learning-welcome-lux">${lux}<span>Let’s make this about you.</span></div><h1>Your money.<br>Or a plot twist?</h1><p class="learning-intro">Pick the examples you want to explore with me.</p><div class="learning-choice-list">${effectivePersonal(ctx)?`<button class="learning-choice ${mode==='actual'?'selected':''}" data-learn-mode="actual" aria-pressed="${mode==='actual'}"><span>${icon('plan',25)}</span><div><strong>Use my Lumo activity</strong><small>My confirmed money and plans. Just between me and Lux.</small></div>${icon(mode==='actual'?'check':'chevron',18)}</button>`:`<div class="learning-privacy-note">${icon('lock',20)}<p>Personalisation is off in your account preferences. Student examples are ready for you.</p></div>`}<button class="learning-choice ${mode==='example'?'selected':''}" data-learn-mode="example" aria-pressed="${mode==='example'}"><span>${icon('spark',25)}</span><div><strong>Take me into a student story</strong><small>Campus situations. Sample money. Same points.</small></div>${icon(mode==='example'?'check':'chevron',18)}</button></div><details class="learning-quiet-details"><summary>What stays private? ${icon('chevron',15)}</summary><p>Your learning, balances and reflections stay private. Nothing goes into group chat or campus rankings. Change this choice any time.</p></details>${error()}</div>${footer(button('Let’s do this','enrol',{disabled:!mode})+'<button class="learning-text" data-learn-action="start-back">Change my focus</button>')}`,{className:'learning-task learning-start'});
 return frame('Learn with Lux',`${beats(0,['Your focus','Your examples','Let’s go'])}<div class="learning-body"><div class="learning-welcome-lux">${lux}<span>Hey. I’m in your corner.</span></div><p class="eyebrow">Money has plot twists.</p><h1>Let’s get good<br>at the next move.</h1><p class="learning-intro">Campus stories. Your choices. Aha moments.<br>What’s on your mind?</p><div class="learning-goals">${LEARNING_GOALS.map((g,index)=>`<button type="button" class="learning-goal ${goal===g.id?'selected':''}" data-learn-goal="${g.id}" aria-pressed="${goal===g.id}"><span>${icon(['calendar','plan','box','lock'][index],25)}</span><strong>${esc(g.title)}</strong>${goal===g.id?icon('check',17):''}</button>`).join('')}</div>${error()}</div>${footer(button('That’s my focus','start-next',{disabled:!goal})+'<p class="learning-fine">Your pace. Every useful move counts.</p>')}`,{className:'learning-task learning-start'});
}
function home(ctx){
 const v=model(ctx);if(!v.enrolled)return start(ctx);
 const d=ui(ctx),tab=d.playTab||'play',n=v.nudge||getLearningNudge(ctx.state,options(ctx)),topics=v.topics||[],streak=v.streak||{},xp=v.points??v.xp??0,goalTopic={allowance:'planning',upcoming:'upcoming',saving:'saving',safety:'safety'}[v.goal]||'planning',chosen=topics.find(t=>t.id===(d.topic||goalTopic))||topics[0],all=topics.flatMap(t=>t.lessons||[]),next=(topics.find(t=>t.id===goalTopic)?.lessons||[]).find(l=>!l.completed)||all.find(l=>!l.completed)||all[0];
 return frame('Learn with Lux',`${moneyIQEntry()}${tab!=='play'?`<div class="learning-mini-progress"><button data-learn-action="progress" aria-label="View my learning progress">${tab==='play'?`<span>${icon('spark',16)} My learning progress ${icon('chevron',14)}</span>`:`<span>${icon('spark',16)} ${xp} points</span><span>${icon('repeat',16)} ${streak.current||0} week${streak.current===1?'':'s'}</span><span>Level ${v.level?.number||1} ${icon('chevron',14)}</span>`}</button><button class="learning-settings" data-learn-action="preferences" aria-label="Learning preferences">${icon('settings',19)}</button></div>`:''}${tab!=='play'?`<div class="learning-dashboard-head"><div><p class="eyebrow">A minute with Lux</p><h1>Life happens.<br>Let’s play it out.</h1></div><div class="learning-lux-dashboard">${lux}</div></div>`:''}<div class="learning-home-tabs" role="group" aria-label="Explore learning"><button data-learning-tab="play" aria-pressed="${tab==='play'}" class="${tab==='play'?'selected':''}">Play</button><button data-learning-tab="stories" aria-pressed="${tab==='stories'}" class="${tab==='stories'?'selected':''}">Stories</button><button data-learning-tab="money" aria-pressed="${tab==='money'}" class="${tab==='money'?'selected':''}">My money</button></div>${v.recoveryNotice?`<div class="learning-privacy-note">${icon('info',20)}<p>${esc(v.recoveryNotice)}</p></div>`:''}${tab!=='play'&&v.currentPracticeSessionId?`<button class="learning-resume" data-learning-resume="${esc(v.currentPracticeSessionId)}">${icon('repeat',18)} Pick up my money moment ${icon('arrow',17)}</button>`:''}${tab==='play'?renderCampusGameEntry(ctx):tab==='stories'?`${next?storyFeature(next):''}<div class="learning-section-heading"><h2>Pick your next plot twist</h2><span>1 minute each</span></div><div class="learning-topic-picks" role="group" aria-label="Money story topics">${topics.map(t=>`<button data-learning-topic="${esc(t.id)}" aria-pressed="${chosen?.id===t.id}" class="${chosen?.id===t.id?'selected':''}">${topicIcon(t)}<span>${esc(t.title)}</span></button>`).join('')}</div>${chosen?`<section class="learning-story-deck" aria-label="${esc(chosen.title)} stories">${(chosen.lessons||[]).map(l=>{const scene=sceneFor(l);return `<button data-learn-lesson="${esc(l.id)}" class="learning-story-row"><span class="learning-story-emoji" aria-hidden="true">${esc(scene.emoji||'✦')}</span><div><small>${l.completed?'A story you’ve explored':'Your move next'}</small><strong>${esc(scene.headline||l.title)}</strong></div>${icon(l.completed?'check':'arrow',19)}</button>`;}).join('')}</section>`:''}${(v.dueReviews||[]).length?`<div class="learning-section-heading"><h2>The plot thickens</h2><span>A new twist</span></div>${v.dueReviews.map(r=>`<button class="learning-review-row" data-learn-review="${esc(r.lessonId||r.id)}"><span>${icon('repeat',22)}</span><div><strong>${esc(r.title)}</strong><small>Same idea. New situation. What would you do?</small></div>${icon('arrow',18)}</button>`).join('')}`:''}`:`${luxLine('Let’s bring this into your world. Start with a picture, make a move, then decide what’s next.')}<div class="learning-missions">${(v.practices||[]).map(p=>`<button class="learning-mission" data-learn-practice="${esc(p.id)}"><span aria-hidden="true">${p.id==='incoming-plan'?'↗':'↻'}</span><div><small>${p.id==='incoming-plan'?'Money landed':'Your week, unwrapped'}</small><strong>${p.id==='incoming-plan'?'Give it a game plan.':'How’s your money doing?'}</strong><p>${esc(p.description)}</p></div>${icon('arrow',21)}</button>`).join('')}</div>${n?`<button class="learning-next" data-learn-action="nudge"><span>${lux}</span><div><small>A moment for you</small><strong>${esc(n.title||'Something worth a look.')}</strong><p>${esc(n.description||n.body||'Let’s take a look together.')}</p></div>${icon('arrow',18)}</button>`:''}<p class="learning-fine">${esc(localPrivacy(ctx))}. Examples offer the same progress. Your money stays put unless you choose a financial action.</p>`}`,{className:`learning-dashboard ${tab==='play'?'learning-game-home':''}`,back:false});
}
function lesson(ctx,r){
 const v=getLearningLesson(ctx.state,r.id,options(ctx));if(!v)return missing('This story is not here.');
 const d=ui(ctx),scene=sceneFor(v),story=d.lessonStory?.[v.sessionId||v.id]===true||v.status==='ready'||(r.page==='review'&&!v.review),topic=LEARNING_TOPICS.find(t=>t.id===v.topicId),answered=Number.isInteger(v.selected)||['answered','completed'].includes(v.status),correct=v.correct===true;
 if(r.page==='review'&&!v.review&&!v.reviewAvailable)return frame('Back for a new twist',`<div class="learning-body learning-centred"><div class="learning-lux-hero">${lux}</div><h1>Let that one<br>sink in.</h1><p class="learning-intro">We’ll put the idea into a new situation later. ${v.reviewDueAt?`Your next twist is ready from ${dateLabel(v.reviewDueAt)}.`:'Explore this story first, then come back for a new twist.'}</p></div>${footer(button('Back to my stories','learning-home'))}`,{className:'learning-task'});
 if(story)return frame(r.page==='review'?'A new twist':topic?.title||'A money moment',`${beats(0)}<div class="learning-body learning-scene-body"><div class="learning-scene-label">${esc(r.page==='review'?'Same idea, new situation':scene.eyebrow||'A campus money moment')}<span>${r.page==='review'?'New twist':'Student story'}</span></div><h1>${esc(r.page==='review'?'Let’s play it\nout again.':scene.headline||v.title)}</h1><div class="learning-scene-stage"><span class="learning-scene-emoji" aria-hidden="true">${r.page==='review'?icon('repeat',65):esc(scene.emoji||'✦')}</span><div class="learning-scene-lux">${lux}</div><span class="learning-scene-orbit orbit-one" aria-hidden="true"></span><span class="learning-scene-orbit orbit-two" aria-hidden="true"></span></div>${r.page==='review'?luxLine('New situation, same useful idea. Ready to make the call?'):sceneChat(scene,d.storyChat?.[v.id]||1,v.id)}${error()}</div>${footer(button(r.page==='review'?'Make my move':scene.choiceLabel||'What’s your move?','lesson-begin',{extra:`data-lesson-id="${esc(v.id)}"`})+'<p class="learning-fine">A sample story. Explore freely, your money stays put.</p>')}`,{className:'learning-task learning-lesson learning-scene'});
 if(correct)return frame('The takeaway',`${beats(2)}<div class="learning-body learning-payoff"><div class="learning-celebration"><span aria-hidden="true">✦</span><div>${lux}</div><span aria-hidden="true">✧</span></div><p class="eyebrow">That’s a move worth keeping.</p><h1>${esc(r.page==='review'?'An idea worth keeping.':scene.winTitle||'Now that’s a useful move.')}</h1><div class="learning-takeaway"><span>Lux’s take</span><p>${esc(v.explanation)}</p></div><p class="learning-payoff-note">${esc(r.page==='review'?'Carry the idea into your next money moment.':scene.winBody||'Keep this one for your next money moment.')}</p>${error()}</div>${footer(button(r.page==='review'?'See my progress':(model(ctx).effectivePersonalised??model(ctx).personalised)?'Try it with my money':'Try a money moment',r.page==='review'?'progress':'lesson-practice')+'<button class="learning-text" data-learn-action="learning-home">Pick another story</button>')}`,{className:'learning-task learning-lesson learning-complete'});
 return frame(r.page==='review'?'A new twist':'Your move',`${beats(1)}<div class="learning-body learning-decision"><div class="learning-decision-buddy">${lux}<span>${r.page==='review'?'A fresh situation':'You’re in the story now.'}</span></div><h1 class="learning-question">${esc(v.question)}</h1>${questionOptions(v,'lesson')}${answered&&!correct?`<div class="learning-answer is-helpful" aria-live="polite"><span>${lux}</span><div><strong>Let’s look at it together.</strong><p>${esc(v.explanation)}</p><small>Try another move. No points lost.</small></div></div>`:''}${error()}</div>${footer('<p class="learning-fine">Tap the move you’d make. Lux has your back.</p>')}`,{className:'learning-task learning-lesson'});
}
function questionOptions(v,kind){const amounts=(v.options||[]).every(label=>/^GH[₵¢][\d,.]+$/.test(label));return `<div class="learning-options ${amounts?'learning-money-tickets':''}" role="group" aria-label="Choose your next move">${(v.options||[]).map((label,index)=>`<button type="button" class="learning-option ${v.selected===index?'selected':''}" data-learn-answer="${kind}" data-option="${index}" aria-pressed="${v.selected===index}" ${v.correct?'disabled':''}><span>${amounts?`<span class="learning-ticket-currency">GH₵</span><span class="learning-ticket-number">${esc(label.replace(/^GH[₵¢]/,""))}</span>`:esc(label)}</span>${icon('arrow',19)}</button>`).join('')}</div>`;}
function practiceRecords(v,hidden){
 const movements=v.movements||[],upcoming=v.upcoming||[];
 return `<details class="learning-records"><summary>${icon('calendar',17)} ${v.kind==='weekly-review'?'Behind this week':'Behind this picture'} ${icon('chevron',15)}</summary>${v.kind==='weekly-review'&&movements.length?`<div class="learning-record-list"><span class="eyebrow">${v.mode==='actual'?'Confirmed recorded moves':'Sample money moves'}</span>${movements.map(m=>`<div><span>${esc(m.title)}</span><strong class="${m.direction==='in'?'accent':''}">${hidden?'••••.••':`${m.direction==='in'?'+':'−'}${cash(m.amount)}`}</strong></div>`).join('')}</div>`:''}${upcoming.length?`<div class="learning-record-list"><span class="eyebrow">Coming up or needing attention</span>${upcoming.map(item=>`<div><span>${esc(item.title)}<small>${item.overdue?'Overdue · ':'Due '}${dateLabel(item.due)}</small></span><strong>${hidden?'••••.••':cash(item.amount)}</strong></div>`).join('')}</div>`:'<p>No upcoming budget costs are recorded for the next seven days. Anything missing can go into your plan.</p>'}<p>${esc(v.sourceLabel||'Based on records in this prototype.')}</p><p>${v.mode==='actual'?'Only confirmed recorded money counts here. Expected allowances and unpaid IOUs stay outside available money. Cash, other banks and costs you have not entered may change the picture.':'These are example records for practice. Expected money stays separate from available money.'}</p></details>`;
}
function moneyPicture(v,hidden,{compact=false}={}){const stats=v.stats||[];return `<div class="learning-money-picture ${compact?'compact':''}"><span class="learning-picture-label">${v.mode==='actual'?'My recorded Lumo money':'Student example'}<i aria-hidden="true">${icon('lock',13)}</i></span>${stats.map((stat,i)=>`<div class="${i===stats.length-1&&v.summary?.hasPlan?'picture-flex':''}"><span>${esc(stat.label)}</span><strong>${hidden?'••••.••':cash(stat.value)}</strong></div>`).join('')}</div>`;}
function practice(ctx,r){
 const v=getLearningPractice(ctx.state,r.id||'incoming-plan',options(ctx));if(!v)return missing('This money moment is not here.');
 const d=ui(ctx),dashboard=model(ctx),kind=v.kind||v.id,ready=v.status==='ready',actual=v.mode==='actual',hidden=actual&&ctx.state.settings.hideBalance&&!d.revealed?.[v.sessionId],stale=v.status==='stale'||d.staleSession===v.sessionId;
 if(ready){const chosen=d.practiceMode?.[kind]||((dashboard.effectivePersonalised??dashboard.personalised)&&v.actualAvailable?'actual':'example');return frame('Into your world',`<div class="learning-body"><div class="learning-welcome-lux">${lux}<span>${kind==='weekly-review'?'Let’s unwrap your week.':'Money landed? Let’s give it a plan.'}</span></div><h1>${kind==='weekly-review'?'Your week.<br>The money edition.':'A plan before<br>the group plans.'}</h1><p class="learning-intro">${kind==='weekly-review'?'See the picture. Spot what changed. Choose your next move.':'See what needs a job, what needs a cushion, and what has room to play.'}</p><div class="learning-choice-list">${(dashboard.effectivePersonalised??dashboard.personalised)&&v.actualAvailable?`<button class="learning-choice ${chosen==='actual'?'selected':''}" data-practice-mode="actual" aria-pressed="${chosen==='actual'}"><span>${icon('plan',25)}</span><div><strong>Use my recorded money</strong><small>My confirmed Lumo activity and plans.</small></div>${icon(chosen==='actual'?'check':'chevron',18)}</button>`:`<div class="learning-privacy-note">${icon('info',20)}<p>${dashboard.personalised?'Not enough confirmed activity for this one yet. Step into a student example instead.':'You’re using student examples. Change this in learning preferences any time.'}</p></div>`}<button class="learning-choice ${chosen==='example'?'selected':''}" data-practice-mode="example" aria-pressed="${chosen==='example'}"><span>${icon('spark',25)}</span><div><strong>Use a student example</strong><small>Same useful ideas. Same progress.</small></div>${icon(chosen==='example'?'check':'chevron',18)}</button></div><p class="learning-fine">Private to you. Looking around won’t move money or save a budget.</p>${error()}</div>${footer(button('Let’s have a look','practice-begin',{extra:`data-practice-kind="${esc(kind)}"`}))}`,{className:'learning-task learning-practice'});}
 if(stale)return frame('A fresh picture',`<div class="learning-body learning-centred"><div class="learning-lux-hero">${lux}</div><h1>Your money<br>has moved on.</h1><p class="learning-intro">Something changed while we were here. Let’s get the latest picture before choosing a move.</p><p class="learning-fine">Your earlier learning and points stay yours.</p>${error()}</div>${footer(button('Refresh my exercise','practice-refresh',{extra:`data-practice-kind="${esc(kind)}"`}))}`,{className:'learning-task'});
 if(v.status==='completed')return frame('A move for real life',`${beats(2,['The picture','Your move','What’s next'])}<div class="learning-body learning-payoff"><div class="learning-celebration"><span aria-hidden="true">✦</span><div>${lux}</div><span aria-hidden="true">✧</span></div><p class="eyebrow">You showed up for your money.</p><h1>That’s how<br>clarity happens.</h1><p class="learning-intro">${actual?'You looked at your recorded money and chose what needs attention.':'You played out a student money moment and found a useful next move.'}</p><p class="learning-payoff-note">No perfect week needed. Keep checking in.</p>${error()}</div>${footer(button('Back to my stories','learning-home')+'<button class="learning-text" data-learn-action="progress">See my progress</button>')}`,{className:'learning-task learning-complete'});
 const hasPlan=v.summary?.hasPlan===true,correct=v.correct===true,reflection=d.reflection?.[v.sessionId]||'',reflectionOptions=v.reflectionOptions||[],stage=d.practiceStage?.[v.sessionId]||(correct?'reflect':'picture');
 if(stage==='picture'||hidden)return frame(kind==='weekly-review'?'Your week, unwrapped':'Your money picture',`${beats(0,['The picture','Your move','What’s next'])}<div class="learning-body"><p class="eyebrow">${actual?'Your world. Your pace.':'Let’s play this out.'}</p><h1>${kind==='weekly-review'?'Here’s the week<br>so far.':'First, the<br>money picture.'}</h1>${moneyPicture(v,hidden)}${v.evidence?'<p class="learning-evidence">You reviewed your plan after answering. These figures show your latest recorded money.</p>':''}${hidden?luxLine('Your amounts are hidden. Reveal them for this moment only. Your usual balance preference stays on.'):luxLine(kind==='weekly-review'?'A check-in starts with what’s here, not what you hoped would arrive.':'Some money already has a job. Let’s find the room that’s really yours.')}${practiceRecords(v,hidden)}${error()}</div>${footer(button(hidden?'Show amounts for this exercise':correct?'Back to my next move':'I see it. What’s my move?',hidden?'practice-reveal':'practice-choice'))}`,{className:'learning-task learning-practice learning-picture'});
 if(!correct)return frame('Your move',`${beats(1,['The picture','Your move','What’s next'])}<div class="learning-body learning-decision">${luxLine(hasPlan?'After commitments and cushion, this is the room for your plans.':'Before calling any money flexible, give the essentials a place in your plan.')}${moneyPicture(v,false,{compact:true})}<h1 class="learning-question">${hasPlan?'Pick the room<br>for your plans.':'Give the essentials<br>a place first.'}</h1>${questionOptions(v,'practice')}${Number.isInteger(v.selected)&&v.correct===false?`<div class="learning-answer is-helpful" aria-live="polite"><span>${lux}</span><div><strong>Let’s look at it together.</strong><p>${esc(v.explanation)}</p><small>Try another move. No points lost.</small></div></div>`:''}${error()}</div>${footer('<button class="learning-text" data-learn-action="practice-picture">Look at the full picture</button>')}`,{className:'learning-task learning-practice'});
 return frame('What’s next?',`${beats(2,['The picture','Your move','What’s next'])}<div class="learning-body"><div class="learning-decision-buddy">${lux}<span>${hasPlan?'You’ve found the room.':'Start with what needs covering.'}</span></div><h1>Make the next<br>move yours.</h1><div class="learning-takeaway compact"><span>Lux’s take</span><p>${esc(v.explanation)}</p></div>${v.evidence?'<p class="learning-evidence">Plan updated. The latest picture is ready whenever you want to look.</p>':''}${actual&&(v.routes||[]).length?`<details class="learning-review-links"><summary>Take a money action ${icon('arrow',17)}</summary>${v.routes.map((a,index)=>`<button class="learning-route" data-learning-route="${index}"><span>${esc(a.label)}</span>${icon('arrow',18)}</button>`).join('')}<small>Your usual review and approval steps still apply. Return here when you’re ready.</small></details>`:''}<p class="learning-reflection-prompt">${actual?'What are you taking from this?':'What are you taking into real life?'}</p><div class="learning-reflections">${reflectionOptions.map(choice=>`<button class="learning-reflection ${reflection===choice.id?'selected':''}" data-learning-reflection="${esc(choice.id)}" aria-label="${esc(choice.label)}" aria-pressed="${reflection===choice.id}"><span>${icon(reflection===choice.id?'check':'spark',18)}</span><strong>${esc(reflectionTitle[choice.id]||choice.label)}</strong></button>`).join('')}</div>${reflection?`<p class="learning-reflection-note">${esc(reflectionOptions.find(choice=>choice.id===reflection)?.label||'')}</p>`:''}${error()}</div>${footer(button('Keep that takeaway','practice-complete',{disabled:!reflection})+'<button class="learning-text" data-learn-action="practice-picture">See my current picture</button>')}`,{className:'learning-task learning-practice'});
}

function progress(ctx){
 const v=model(ctx),streak=v.streak||{},activities=v.activities||v.history||[];
 const history=activities.length?activities.slice(0,20).map(a=>`<div><span>${icon(a.type==='review'?'repeat':'check',17)}</span><div><strong>${esc(a.title||'Learning activity')}</strong><small>${dateLabel(a.at)}${a.mode==='actual'?' · Your recorded money':a.mode==='example'?' · Student example':''}</small></div><b>${a.points?`+${a.points}`:'✓'}</b></div>`).join(''):'<p>Your first lesson or money check starts your progress. Small steps count.</p>';
 return frame('Your learning progress',`<div class="learning-body">
  <div class="learning-progress-intro"><h1>Your pace.<br>Your progress.</h1></div>${score(v)}
  <div class="learning-momentum"><div><span>${icon('spark',20)} ${v.points??v.xp??0} points</span><small>Learning and practice</small></div><div><span>${icon('repeat',20)} ${streak.current||0}-week streak</span><small>Longest: ${streak.longest||0} weeks</small></div></div>
  <div class="learning-streak-card"><span class="eyebrow">Your weekly rhythm</span><strong>${esc(streakText(streak))}</strong><div class="learning-week-dots" aria-label="${streak.thisWeekActivities||0} of ${streak.target||2} learning activities">${Array.from({length:streak.target||2},(_,i)=>`<span class="${i<(streak.thisWeekActivities||0)?'done':''}">${icon(i<(streak.thisWeekActivities||0)?'check':'spark',21)}</span>`).join('')}</div><p>Two meaningful activities make a learning week. Your money does not need to move.</p>${streak.graceAvailable&&!streak.graceActive?'<button class="learning-text" data-learn-action="grace">Take a grace week</button>':''}${streak.graceActive?'<p class="learning-grace">A grace week is active. Come back at your pace; your completed learning stays here.</p>':''}</div>
  <div class="learning-section-heading"><h2>Skills you’re building</h2></div><div class="learning-skills">${(v.topics||[]).map(t=>`<div class="learning-skill"><span>${topicIcon(t)}</span><div><strong>${esc(t.title)}</strong><div class="learning-skill-tags">${tag(t.understood?'Understood ✓':'Building understanding')}${tag(t.practised?t.practiceSource==='story'?'Story practice ✓':'Practised ✓':'Practice next')}${tag(t.retained?'Remembered ✓':'Fresh check later')}</div></div></div>`).join('')}</div>
  <details class="learning-history-details"><summary>Your little wins ${icon('chevron',16)}</summary><div class="learning-history">${history}</div></details>
  <details class="learning-quiet-details"><summary>How your level works ${icon('chevron',16)}</summary>${v.level?.next?`<p class="learning-next-level"><strong>Next little milestone</strong>${esc(v.level.next)}</p>`:''}<p>Your points recognise participation. Your learning level grows with understanding, practice and later knowledge checks.</p><p>Up to ${v.weeklyPointsLimit||100} points each week. Completed skills and learning activities continue to count after that.</p><p>Your level is a private Lumo learning milestone. Story practice recognises skills tried with fictional money, not proof of real-money habits. Your level does not rate your wealth, decide access to banking or certify financial expertise.</p></details>${error()}
 </div>`,{className:'learning-progress'});
}

function preferences(ctx){const v=model(ctx),d=ui(ctx),goal=d.preferenceGoal||v.goal,personal=d.preferenceMode||((v.effectivePersonalised??v.personalised)?'actual':'example');return frame('Your learning, your way',`<div class="learning-body"><h1>Keep it<br>useful for you.</h1><p class="learning-intro">A new focus can fit a new term. Your completed learning stays yours.</p><div class="learning-section-heading"><h2>My focus</h2></div><div class="learning-preference-goals">${LEARNING_GOALS.map(g=>`<button class="learning-reflection ${goal===g.id?'selected':''}" data-preference-goal="${g.id}" aria-pressed="${goal===g.id}">${icon(goal===g.id?'check':'spark',18)}<span>${esc(g.title)}</span></button>`).join('')}</div><div class="learning-section-heading"><h2>My practice examples</h2></div><div class="learning-choice-list">${effectivePersonal(ctx)?`<button class="learning-choice ${personal==='actual'?'selected':''}" data-preference-mode="actual" aria-pressed="${personal==='actual'}"><span>${icon('plan',24)}</span><div><strong>My recorded Lumo activity</strong><small>Private, relevant practice from confirmed records.</small></div>${icon(personal==='actual'?'check':'chevron',18)}</button>`:'<p class="learning-privacy-note">Personalised learning is off. Your learning can continue with examples.</p>'}<button class="learning-choice ${personal==='example'?'selected':''}" data-preference-mode="example" aria-pressed="${personal==='example'}"><span>${icon('spark',24)}</span><div><strong>Student examples</strong><small>The same learning points and opportunity to progress.</small></div>${icon(personal==='example'?'check':'chevron',18)}</button></div><p class="learning-fine">Switching to examples clears unfinished personalised exercises. Completed points and learning remain. Your balances and reflections are private.</p>${error()}</div>${footer(button('Save my learning preferences','save-preferences'))}`,{className:'learning-task'});}
function missing(text){return frame('Learn with Lux',`<div class="learning-body learning-centred"><div class="learning-lux-hero">${lux}</div><h1>Let’s pick that<br>up again.</h1><p class="learning-intro">${esc(text)}</p></div>${footer(button('Back to my learning','learning-home'))}`,{className:'learning-task'});}

export function renderLearning(ctx,r=ctx.route){if(['money-iq','home'].includes(r.page))return renderMoneyIQ(ctx,r);if(!model(ctx).enrolled&&!['start','preferences'].includes(r.page))return start(ctx);if(['game','play','rewards'].includes(r.page))return renderCampusGame(ctx,r);return ({library:home,start,lesson,practice,progress,preferences,review:lesson}[r.page]||home)(ctx,r);}
export function renderLearningEntry(ctx){const v=model(ctx);return `<button class="learning-menu-entry" data-action="open-learning"><span class="learning-entry-lux">${lux}</span><span><strong>Learn with Lux</strong><small>${v.enrolled?`Money IQ · ${v.points??v.xp??0} learning points`:'Money IQ · Play your week with Lux'}</small></span>${icon('chevron',18)}</button>`;}

function bindLearningMotion(ctx,r,root){
 const off=ctx.draft.campusMotionOff===true;
 root.classList?.add('learning-motion-scope');root.classList?.toggle('campus-motion-off',off);
 const control=root.querySelector?.('[data-learn-action="toggle-motion"]'),entry=root.querySelector?.('.campus-game-entry');
 const media=typeof globalThis.matchMedia==='function'?globalThis.matchMedia('(prefers-reduced-motion: reduce)'):null;
 const updateControl=()=>{const deviceReduced=media?.matches===true,enabled=!off&&!deviceReduced;if(control){control.disabled=deviceReduced;control.hidden=!!entry;}control?.setAttribute?.('aria-pressed',String(enabled));control?.setAttribute?.('aria-label',deviceReduced?'Reduced motion follows your device settings':enabled?'Animations on. Turn off':'Animations off. Turn on');control?.setAttribute?.('title',deviceReduced?'Reduced motion is on in device settings':enabled?'Pause animations':'Resume animations');control?.classList?.toggle('is-off',!enabled);};
 updateControl();
 if(!root.querySelectorAll||entry)return ()=>{};
 media?.addEventListener?.('change',updateControl);
 const mark=(selector,kind)=>[...root.querySelectorAll(selector)].forEach((el,i)=>{el.setAttribute('data-motion',kind);el.setAttribute('data-motion-index',String(i));});
 mark('h1','title');mark('.learning-intro,.learning-story,.learning-chat-bubble,.learning-lux-line,.learning-takeaway,.learning-context-label,.learning-answer,.learning-payoff-note','body');
 mark('.learning-scene-stage,.learning-lux-hero,.learning-lux-dashboard,.learning-welcome-lux,.learning-celebration','hero');
 mark('.learning-option,.learning-goal,.learning-choice,.learning-reflection,.learning-story-row,.learning-topic-picks button,.learning-footer>.button','choice');
 const signature=[r.page,r.id||'',root.querySelector('h1')?.textContent||'',root.querySelectorAll('.learning-chat-bubble').length,root.querySelector('.learning-answer')?.className||''].join('|');
 const transition=learningMotionNext.get(ctx)||{direction:'forward',fresh:false},enter=learningMotionLast.get(ctx)!==signature||transition.fresh===true;
 learningMotionNext.delete(ctx);learningMotionLast.set(ctx,signature);
 const dispose=bindCampusMotion(root,{kind:'learning',reduced:off,enter,transition,particles:false,celebrate:transition.fresh===true});
 return ()=>{dispose?.();media?.removeEventListener?.('change',updateControl);};
}

export function bindLearning(ctx,r=ctx.route){
 if(['money-iq','home'].includes(r.page))return bindMoneyIQ(ctx,r);
 if(model(ctx).enrolled&&['game','play','rewards'].includes(r.page))return bindCampusGame(ctx,r);
 const root=ctx.$('.learning-page');if(!root)return ()=>{};let alive=true,busy=false;
 const valid=()=>alive&&root.isConnected&&ctx.route.section==='learn';
 const d=ui(ctx);d.lessonStory ||= {};d.reflection ||= {};d.revealed ||= {};d.practiceMode ||= {};d.practiceStage ||= {};d.storyChat ||= {};
 const showError=message=>{const el=ctx.$('[data-learning-error]');if(el)el.textContent=message;else ctx.toast(message);};
 const go=route=>{if(route.section==='learn'){if(!learningMotionNext.has(ctx))learningMotionNext.set(ctx,{direction:'forward',fresh:false});}else learningMotionNext.delete(ctx);ctx.saveDraft?.();ctx.go(route);};
 const act=(type,payload,onSuccess)=>{if(busy||!valid())return;busy=true;const result=ctx.act(type,payload);busy=false;if(!result.ok){showError(result.message||'Let’s try that again.');if(/changed|stale|latest|refresh/i.test(result.message||'')&&r.page==='practice'){const v=getLearningPractice(ctx.state,r.id,options(ctx));d.staleSession=v?.sessionId;ctx.refresh();showError(result.message);}return;}onSuccess?.(result);};
 const startLesson=(id,review=false,story=true)=>act('learningStartLesson',{lessonId:id,review},result=>{d.lessonStory[result.sessionId||id]=story;go({section:'learn',page:review?'review':'lesson',id,...(r.returnTo?{returnTo:r.returnTo}:{})});});
 const beginPractice=(kind,mode)=>act('learningStartPractice',{kind,mode},result=>{delete d.staleSession;d.practiceStage[result.sessionId]='picture';go({section:'learn',page:'practice',id:result.sessionId||kind,...(r.returnTo?{returnTo:r.returnTo}:{})});});
 const click=e=>{
  const b=e.target.closest('button');if(!b||b.disabled||!valid())return;
  if(b.dataset.learnStoryChat){const id=b.dataset.learnStoryChat;d.storyChat[id]=(d.storyChat[id]||1)+1;ctx.saveDraft?.();ctx.refresh();return;}
  if(b.dataset.learningTab){d.playTab=b.dataset.learningTab;ctx.saveDraft?.();ctx.refresh();return;}
  if(b.dataset.learningTopic){d.topic=b.dataset.learningTopic;ctx.saveDraft?.();ctx.refresh();return;}
  if(b.dataset.learnGoal){d.goal=b.dataset.learnGoal;ctx.refresh();return;}
  if(b.dataset.learnMode){d.mode=b.dataset.learnMode;ctx.refresh();return;}
  if(b.dataset.learnLesson){startLesson(b.dataset.learnLesson);return;}
  if(b.dataset.learnReview){startLesson(b.dataset.learnReview,true);return;}
  if(b.dataset.learningResume){go({section:'learn',page:'practice',id:b.dataset.learningResume});return;}
  if(b.dataset.learnPractice){go({section:'learn',page:'practice',id:b.dataset.learnPractice});return;}
  if(b.dataset.practiceMode){const v=getLearningPractice(ctx.state,r.id,options(ctx));d.practiceMode[v.kind||v.id]=b.dataset.practiceMode;ctx.refresh();return;}
  if(b.dataset.preferenceGoal){d.preferenceGoal=b.dataset.preferenceGoal;ctx.refresh();return;}
  if(b.dataset.preferenceMode){d.preferenceMode=b.dataset.preferenceMode;ctx.refresh();return;}
  if(b.dataset.learningReflection){const v=getLearningPractice(ctx.state,r.id,options(ctx));d.reflection[v.sessionId]=b.dataset.learningReflection;ctx.refresh();return;}
  if(b.dataset.learnAnswer){
   const kind=b.dataset.learnAnswer,v=kind==='lesson'?getLearningLesson(ctx.state,r.id,options(ctx)):getLearningPractice(ctx.state,r.id,options(ctx));
   if(!v?.sessionId)return;
   act(kind==='lesson'?'learningAnswer':'learningAnswerPractice',{sessionId:v.sessionId,option:Number(b.dataset.option)},result=>{if(result.correct&&result.points>0)learningMotionNext.set(ctx,{direction:'forward',fresh:true});if(kind==='practice'&&getLearningPractice(ctx.state,r.id,options(ctx))?.correct)d.practiceStage[v.sessionId]='reflect';ctx.refresh({scroll:0});});return;
  }
  if(b.dataset.learningRoute!==undefined){const v=getLearningPractice(ctx.state,r.id,options(ctx)),action=v?.routes?.[Number(b.dataset.learningRoute)];if(!action?.route)return;const returnTo={section:'learn',page:'practice',id:v.sessionId,...(r.returnTo?{returnTo:r.returnTo}:{})};ctx.draft.learningReturnTo=returnTo;go({...action.route,returnTo});return;}
  const action=b.dataset.learnAction;if(!action)return;
  if(action==='toggle-motion'){ctx.draft.campusMotionOff=!ctx.draft.campusMotionOff;ctx.saveDraft?.();ctx.refresh();return;}
  if(action==='home'){go({section:'home',page:'home'});return;}
  if(action==='money-iq'){go({section:'learn',page:'money-iq'});return;}
  if(action==='learning-home'){delete ctx.draft.learningReturnTo;go(HOME);return;}
  if(action==='choose-focus'){d.startStep='goal';ctx.refresh({scroll:0});return;}
  if(action==='quick-play'){act('learningEnroll',{goal:d.goal||model(ctx).goal||'allowance',personalised:false},()=>act('campusStart',{missionId:getCampusGame(ctx.state).nextMissionId},result=>{delete ctx.draft.learningUI;go({section:'learn',page:'play',id:result.runId});}));return;}
  if(action==='start-back'){d.startStep='goal';ctx.refresh();return;}
  if(action==='start-next'){if(!d.goal&&!model(ctx).goal){showError('Choose the focus that feels useful for you.');return;}d.startStep='mode';ctx.refresh();return;}
  if(action==='enrol'){act('learningEnroll',{goal:d.goal||model(ctx).goal,personalised:d.mode==='actual'&&effectivePersonal(ctx)},()=>{delete ctx.draft.learningUI;go(HOME);});return;}
  if(action==='preferences'){go({section:'learn',page:'preferences'});return;}
  if(action==='save-preferences'){act(model(ctx).enrolled?'learningPreferences':'learningEnroll',{goal:d.preferenceGoal||model(ctx).goal,personalised:(d.preferenceMode||(model(ctx).personalised?'actual':'example'))==='actual'&&effectivePersonal(ctx)},()=>{delete ctx.draft.learningUI;delete ctx.draft.learningReturnTo;ctx.toast('Your learning preferences are saved.');go(r.returnTo?.section==='learn'&&r.returnTo.page==='money-iq'?r.returnTo:HOME);});return;}
  if(action==='progress'){go({section:'learn',page:'progress'});return;}
  if(action==='lesson-begin'){const v=getLearningLesson(ctx.state,r.id,options(ctx));if(v.status==='ready'||(r.page==='review'&&!v.review))startLesson(v.id,r.page==='review',false);else{d.lessonStory[v.sessionId||v.id]=false;ctx.refresh({scroll:0});}return;}
  if(action==='lesson-practice'){const v=getLearningLesson(ctx.state,r.id,options(ctx));go({section:'learn',page:'practice',id:['planning','expected','upcoming'].includes(v.topicId)?'incoming-plan':'weekly-review',...(r.returnTo?{returnTo:r.returnTo}:{})});return;}
  if(action==='practice-begin'||action==='practice-refresh'){const v=getLearningPractice(ctx.state,r.id,options(ctx)),kind=b.dataset.practiceKind||v.kind||v.id,mode=d.practiceMode[kind]||(v.actualAvailable&&(model(ctx).effectivePersonalised??model(ctx).personalised)?'actual':'example');beginPractice(kind,mode);return;}
  if(action==='practice-choice'){const v=getLearningPractice(ctx.state,r.id,options(ctx));d.practiceStage[v.sessionId]=v.correct?'reflect':'choice';ctx.saveDraft?.();ctx.refresh({scroll:0});return;}
  if(action==='practice-picture'){learningMotionNext.set(ctx,{direction:'back',fresh:false});const v=getLearningPractice(ctx.state,r.id,options(ctx));d.practiceStage[v.sessionId]='picture';ctx.saveDraft?.();ctx.refresh({scroll:0});return;}
  if(action==='practice-reveal'){const v=getLearningPractice(ctx.state,r.id,options(ctx));d.revealed[v.sessionId]=true;ctx.refresh();return;}
  if(action==='practice-complete'){const v=getLearningPractice(ctx.state,r.id,options(ctx)),reflection=d.reflection[v.sessionId];if(!reflection){showError('Choose the reflection that fits this check.');return;}act('learningCompletePractice',{sessionId:v.sessionId,reflection},result=>{if(result.points>0)learningMotionNext.set(ctx,{direction:'forward',fresh:true});delete ctx.draft.learningReturnTo;ctx.refresh({scroll:0});});return;}
  if(action==='grace'){ctx.sheet(`<h2>A little breathing room.</h2><p>Take a grace week when studies or life need your attention. Your completed learning stays yours. No points are added for a grace week.</p><button class="button" data-learning-confirm-grace>Take this grace week</button>`,el=>{el.querySelector('[data-learning-confirm-grace]').onclick=()=>{if(!el.isConnected)return;act('learningGraceWeek',{},()=>{ctx.closeSheet();ctx.refresh();});};});return;}
  if(action==='nudge'){const n=model(ctx).nudge||getLearningNudge(ctx.state,options(ctx));if(!n)return;const route=n.route||(n.lessonId?{section:'learn',page:'lesson',id:n.lessonId}:{section:'learn',page:'practice',id:n.practiceId||n.kind||'incoming-plan'});if(route.page==='lesson'){startLesson(route.id);return;}go(route);}
 };
 root.addEventListener('click',click);const disposeGameEntry=bindCampusGameEntry(ctx),disposeMotion=bindLearningMotion(ctx,r,root);return ()=>{alive=false;root.removeEventListener('click',click);disposeGameEntry?.();disposeMotion?.();};
}
